void set_read_phase(u8 phase)
{
	(*(unsigned int*)(READ_PHASE_ADDR)) = ((*(unsigned int*)(READ_PHASE_ADDR)) & 0xffffff00) | phase;
	stage1_delay_us(16);
}

void set_write_phase(u8 phase)
{
	(*(unsigned int*)(WRITE_PHASE_ADDR)) = ((*(unsigned int*)(WRITE_PHASE_ADDR)) & 0xffff00ff) | (phase<<8);
	stage1_delay_us(16);
}


int compare_regions(ulv *bufa, ulv *bufb, size_t count) {
    int r = 0;
    size_t i;
    ulv *p1 = bufa;
    ulv *p2 = bufb;
    u8 write_phase_default = (DENALI_CONFIG_PHY[4] >> 8) & 0xFF;
    set_write_phase(write_phase_default);
    for (i = 0; i < count; i++, p1++, p2++)
    {
	
        if (*p1 != *p2)
	{
		r = -1;
		return r;
	}
    }
    r = 0;
    return r;
}

